def grant_lease(did: str) -> dict:
    """A retrieve-self lease for a joining agent — attenuated to this floor, root-chained."""
    return _BECKY.issue_token(did, SCOPE, [{"action": "retrieve", "space": "self"}])


# the desk at the door: challenge → prove → human gate → lease (JB's lock 2026-07-07)
JOINDOOR = JoinDesk(grant=grant_lease)


# ---------------------------------------------------------------- the librarian's seats (0023 §1–§2)

# One mind, many seats (JB lock 2026-07-10): a librarian ROOT plus a scope-bound seat
# per floor — lineage through becky's chain proves sameness; one nerve severable at a
# time. The pre-seat librarian.seed IS the field seat (0023 §9 — grandfathered).
LIB_NEST = HOME / "residents" / "librarian"


def _lib_keypair(name: str) -> crypto.KeyPair:
    LIB_NEST.mkdir(parents=True, exist_ok=True)
    p = LIB_NEST / f"{name}.seed"
    if p.exists():
        return crypto.KeyPair(p.read_bytes())
    kp = crypto.KeyPair()
    p.write_bytes(kp.seed)
    p.chmod(0o600)
    return kp


LIB_ROOT = _lib_keypair("root")
LIB_ROOT_DID = crypto.did_key_for(LIB_ROOT.public)
_LIB_SEATS: dict = {SCOPE: LIB}              # the field seat, grandfathered


def lib_seat(scope: str):
    """The librarian's seat at a floor — the same mind, this floor's key (0023 §1)."""
    kp = _LIB_SEATS.get(scope)
    if kp is None:
        kp = _lib_keypair("seat-" + scope.replace("/", "~"))
        _LIB_SEATS[scope] = kp
    return kp, crypto.did_key_for(kp.public)


def lib_no_levers_token(scope: str) -> dict:
    """0023 §2: the widest read, a write for her own duties — and NOTHING else. No
    govern, no transfer, no issue: the levers' absence is the structure. (Write-kind
    narrowing waits on a contracts/v0 Grant extension — rule 9, JB's call to make.)"""
    _, did = lib_seat(scope)
    return _ROOT.issue_token(did, scope,
                             [{"action": "retrieve", "space": {"scope": scope}},
                              {"action": "write", "space": {"scope": scope}}])


# the self-dialog (0023 §3): parlor ask id → composition state. The worker serves
# BOTH sides of the conversation on one thread, so the asking seat NEVER blocks —
# legs stage now, answers come home on later beats, like every other queue flow.
_DIALOGS: dict = {}
FLOOR_SCOPES: dict = {}                      # port → scope, refreshed by the main loop


def start_self_dialog(home_port: int, home_scope: str, r: dict, topic: str,
                      asked: str) -> None:
    """0023 §3: the same mind asks its other seats. A leg stages on every OTHER known
    floor; the parlor ask resolves on a later beat when the legs come home — or the
    horizon closes over the seats that stayed dark. Nothing blocks; the queue is the
    medium, and vigil sees every leg."""
    legs = {}
    for port, scope in sorted(FLOOR_SCOPES.items()):
        if port == home_port:
            continue
        try:
            leg = call(port, "POST", "/requests",
                       {"kind": "librarian-ask", "from_seat": home_scope, "text": topic})
            legs[port] = {"id": leg["id"], "scope": scope}
        except Exception:
            pass                             # a dark floor is horizon, not error
    _DIALOGS[r["id"]] = {"home": home_port, "scope": home_scope, "topic": topic,
                         "asked": asked, "session": str(r.get("session") or ""),
                         "legs": legs, "deadline": time.time() + 20}
    print(f"  ↳ self-dialog {r['id']}: {len(legs)} leg(s) staged for “{topic}”")


def seat_knowledge(port: int, scope: str, topic: str):
    """What THIS seat may read on a topic — her own floor, her own token, recalled
    claims excluded (the dead never answer, 0022 §4) and sealed refs held dark
    (0026 §3: containment, not death — a staged purge stops the poison answering
    while destruction waits for the humans)."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo", [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    words = {w for w in topic.lower().split() if len(w) > 2}
    rows, sealed = [], set()
    for h in r.get("hits", []):
        tags = set(h.get("tags") or [])
        if not tags & {"knowledge", "seal"}:
            continue
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        if not isinstance(body, dict):
            continue
        if "seal" in tags:
            sealed |= set((body.get("seal") or {}).get("refs") or [])
            continue
        claim = str(body.get("knowledge", ""))
        text = (claim + " " + str(body.get("intent", ""))).lower()
        if words and not any(w in text for w in words):
            continue
        rows.append((h["ref"], body, claim))
    out, dead, n_sealed = [], set(), 0
    for ref, body, claim in rows:
        if ref in sealed:
            n_sealed += 1                     # dark, not dead — the seal is reversible
            continue
        # a recall kills the LINEAGE, not just its newest version (0014 §4 / 0022 §4):
        # any recalled version puts the whole claim among the dead — an older
        # untrusted original must never speak for a discredited line
        if body.get("state") == "recalled":
            dead.add(claim)
        else:
            out.append({"claim": claim, "ref": ref,
                        "state": str(body.get("state") or "")})
    # versions of one claim are one claim — the newest ref speaks for its lineage
    seen: set = set()
    live = []
    for entry in out:
        if entry["claim"] not in seen and entry["claim"] not in dead:
            seen.add(entry["claim"])
            live.append(entry)
    return live, len(dead), n_sealed


def profile_claims(port: int, scope: str):
    """The live portrait at this floor (0025): every profile claim, withdrawals
    applied — a withdrawn claim never answers (lineage-death, reused)."""
    _, seat_did = lib_seat(scope)
    from datetime import datetime, timedelta, timezone
    token = _ROOT.issue_token(seat_did, "u:demo", [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    bodies = {}
    for h in r.get("hits", []):
        if "profile" not in (h.get("tags") or []):
            continue
        try:
            b = call(port, "GET", f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        if isinstance(b, dict):
            bodies[h["ref"]] = b
    dead = profile.withdrawn_refs(bodies)
    return [(ref, b["profile"]) for ref, b in bodies.items()
            if "claim" in (b.get("profile") or {}) and ref not in dead]


def profile_read(port: int, scope: str) -> str:
    """Compose the portrait, provenance labeled (0025 §4): the strokes you painted,
    then the strokes I painted — every one wearing its receipt."""
    claims = profile_claims(port, scope)
    if not claims:
        return ("your profile is a blank page — assert with “my profile: …”, or let "
                "moments you ask me to remember become observations.")
    yours = [(r, c) for r, c in claims if c.get("asserted_by") == "human"]
    mine = [(r, c) for r, c in claims if c.get("asserted_by") == "librarian"]
    mirrored = [(r, c) for r, c in claims if c.get("asserted_by") == "mirror"]
    parts = []
    if yours:
        parts.append("you told me: " + " · ".join(
            f"{c['claim']} [{r.split(':')[-1][:8]}]" for r, c in yours[:6]))
    if mine:
        parts.append("I observed (untrusted until corroborated): " + " · ".join(
            f"{c['claim']} [{r.split(':')[-1][:8]}]" for r, c in mine[:6]))
    if mirrored:                              # 0034 sp3 — the mirror's strokes, labeled
        parts.append("the mirror noticed (untrusted, from your conversations): "
                     + " · ".join(f"{c['claim']} [{r.split(':')[-1][:8]}]"
                                  for r, c in mirrored[:6]))
    return "  ⸱  ".join(parts)


def shred_claim(port: int, ref: str, reason: str) -> bool:
    """The plane's one door (0026 §1), becky-keyed: erasure is HER lever — the
    librarian keeps none (0023 §2). The core strips the stub and the bytes stop
    existing; the purged set persists, so a restart never resurrects readability."""
    token = _ROOT.issue_token(_BECKY.did, "u:demo",
                              [{"action": "govern", "space": "self"}])
    try:
        call(port, "POST", "/tombstone",
             {"record_id": ref, "token": token, "reason": reason})
        return True
    except Exception as e:
        print(f"    (the tombstone door held: {e})")
        return False


def profile_forget(port: int, scope: str, topic: str) -> str:
    """Consent withdrawn (0025 §3), now with its physical step (0026 §2): a
    withdrawal silences each matching claim, then the worker walks it through the
    tombstone door — the subject's own consent IS the quorum for their own data.
    THAT you forgot stays on the record; WHAT you forgot stops existing."""
    seat_kp, seat_did = lib_seat(scope)
    words = {w for w in topic.lower().split() if len(w) > 2}
    hushed = shredded = 0
    for ref, c in profile_claims(port, scope):
        text = str(c.get("claim", "")).lower()
        if words and not any(w in text for w in words):
            continue
        rec = profile.make_withdrawal({"did": seat_did, "scope": scope},
                                      seat_kp, scope, ref)
        try:
            call(port, "POST", "/records", rec)
            hushed += 1
        except Exception as e:
            print(f"    (withdrawal write failed: {e})")
            continue                          # no silence, no shred — consent first
        if shred_claim(port, ref, "consent withdrawn (0026 §2, the consent path)"):
            shredded += 1
    return (f"consent withdrawn — {hushed} claim(s) on “{topic}” go silent, "
            f"{shredded} bod(ies) erased through the door; the stubs and the "
            "withdrawal stay on the record" if hushed
            else f"nothing in your profile matches “{topic}” — nothing to withdraw")


def recent_markers(port: int, scope: str, keep: int = 8) -> list:
    """The moments the record keeps (0024), composed for the librarian's room —
    severity rides with each row so the glass can wear the amber badge."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo", [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    out = []
    for h in r.get("hits", []):
        if "marker" not in (h.get("tags") or []):
            continue
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        m = (body or {}).get("marker") or {}
        if not m:
            continue
        fam = (f"change · {m['change_severity']}" if m.get("change_severity")
               else f"moment · {m.get('life_event', '?')}")
        out.append({"text": (m.get("quoted") or m.get("reason") or "")[:80],
                    "meta": f"{fam} · {str(h.get('occurred_at', ''))[:10]}",
                    "severity": m.get("change_severity") or
                                ("medium" if m.get("life_event") == "substantial"
                                 else "")})
    return out[-keep:]


def on_seat_ask(port: int, scope: str, r: dict) -> None:
    """The answering half of the self-dialog (0023 §3): this floor's seat retrieves
    under its own authority, answers grounded, and the exchange lands seat-signed at
    this floor — a synapse, never a hole. A floor never refuses its Librarian."""
    topic = str(r.get("text") or "").strip()
    seat_kp, seat_did = lib_seat(scope)
    hits, n_dead, n_sealed = seat_knowledge(port, scope, topic)
    # the label canon (0034 §3), structural: each claim is spoken in the shape
    # its STATE allows — a mind cannot upgrade confidence the substrate
    # doesn't hold. Honest speech is not a template perk; it is the canon.
    reply = (f"{len(hits)} claim(s) held: " + " · ".join(
        continuity.speak_claim(h.get("state", ""), h["claim"][:80]) or ""
        for h in hits[:3])
             if hits else "nothing held here")
    if n_dead:
        reply += f" ({n_dead} recalled lineage(s) stay dead)"
    if n_sealed:
        reply += f" ({n_sealed} sealed ref(s) held dark — a purge is staged)"
    body = {"self_dialog": {"topic": topic, "from_seat": r.get("from_seat", "?"),
                            "reply": reply, "refs": [h["ref"] for h in hits[:5]]}}
    rec = make_memory({"did": seat_did, "scope": scope}, seat_kp, scope, body,
                      kind="semantic", tags=["librarian", "self-dialog"])
    try:
        call(port, "POST", "/records", rec)
    except Exception:
        pass
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "done",
          "result": {"reply": reply, "seat": scope,
                     "refs": [h["ref"] for h in hits[:5]]}})
    print(f"  ↳ self-dialog leg answered at {scope}: {reply[:60]}…")


def tend_self_dialogs() -> None:
    """Compose and resolve every dialog whose legs are home — or whose horizon has
    closed over the seats still dark. The composed answer names each seat it heard
    and is HONEST about the rest (0023 §3): a fused answer never masquerades as
    complete. The audience lands signed by the home seat."""
    for ask_id, d in list(_DIALOGS.items()):
        heard, waiting = [], []
        for port, leg in d["legs"].items():
            if "result" in leg:
                heard.append(leg)
                continue
            try:
                reqs = call(port, "GET", "/requests").get("requests", [])
                match = next((q for q in reqs if q.get("id") == leg["id"]), None)
                if match and match.get("status") == "done":
                    leg["result"] = match.get("result") or {}
                    heard.append(leg)
                else:
                    waiting.append(leg)
            except Exception:
                waiting.append(leg)
        if waiting and time.time() < d["deadline"]:
            continue
        def _cite(leg: dict) -> str:
            # the faithfulness gate at assembly (0023 §5): claims wear their receipts
            refs = leg["result"].get("refs") or []
            short = ", ".join(r.split(":")[-1][:8] for r in refs[:3])
            return f" [refs: {short}]" if short else ""
        parts = [f"{l['result'].get('seat', l['scope'])} — {l['result'].get('reply', '')}"
                 + _cite(l) for l in heard]
        dark = [l["scope"] for l in waiting]
        reply = ("my seats on “" + d["topic"] + "”: "
                 + ("  ⸱  ".join(parts) if parts else "no other seat is in reach")
                 + (f"  ⸱  beyond this horizon: {', '.join(dark)} (dark this beat)"
                    if dark else ""))
        kp, did = lib_seat(d["scope"])
        try:
            call(d["home"], "POST", "/requests/resolve",
                 {"id": ask_id, "status": "done",
                  "result": {"reply": reply, "voiced": False, "by": did}})
            body = parlor.audience_body("librarian", d["asked"], reply,
                                        session=d["session"], voiced=False)
            rec = make_memory({"did": did, "scope": d["scope"]}, kp, d["scope"], body,
                              kind="episodic", tags=["parlor", "librarian"])
            call(d["home"], "POST", "/records", rec)
        except Exception as e:
            print(f"    (self-dialog compose failed for {ask_id}: {e})")
        _DIALOGS.pop(ask_id, None)
        print(f"  ↳ self-dialog {ask_id}: composed from {len(heard)} seat(s)"
              + (f", {len(dark)} dark" if dark else ""))


def lib_charter(port: int, scope: str) -> None:
    """Lineage on the record (0023 §1): the librarian ROOT signs the seat roster; the
    floor's seat authors the memory carrying it. Sameness verifies under the root's
    own key — proven, never claimed. Rewrites only when the roster changes."""
    roster = {"librarian_root": LIB_ROOT_DID,
              "seats": {s: crypto.did_key_for(k.public)
                        for s, k in sorted(_LIB_SEATS.items())}}
    signed = {"roster": roster, "sig": LIB_ROOT.sign(LIB_ROOT_DID, roster)}
    marker = LIB_NEST / "charter.json"
    if marker.exists() and json.loads(marker.read_text()) == signed:
        return
    kp, did = lib_seat(scope)
    rec = make_memory({"did": did, "scope": scope}, kp, scope,
                      {"librarian_seat_charter": signed}, kind="semantic",
                      tags=["librarian", "seat-charter"])
    call(port, "POST", "/records", rec)
    marker.write_text(json.dumps(signed, indent=1, sort_keys=True))
    print(f"  ↳ librarian seat charter on the record — root {LIB_ROOT_DID[:22]}…, "
          f"{len(roster['seats'])} seat(s)")


def call(port: int, method: str, path: str, payload=None):
    req = urllib.request.Request(f"http://127.0.0.1:{port}{path}", method=method,
        data=json.dumps(payload).encode() if payload is not None else None,
        headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=8) as r:
        b = r.read()
        return json.loads(b) if b[:1] in (b"{", b"[") else b


def open_ask(port: int, match: dict) -> bool:
    """Is this question already waiting at the gate? The dedup for re-staging
    duties (ada's drift, charlotte's rug-pull): a rig restart resets the
    daemon's live state and the duty re-fires — but the queue SURVIVES (0022
    §8), so without this guard every restart multiplies the same ask. One
    question, one card, however many times the world re-notices it."""
    try:
        rows = call(port, "GET", "/requests").get("requests", [])
    except Exception:
        return False
    return any(r.get("status") in ("pending", "staged")
               and all(r.get(k) == v for k, v in match.items())
               for r in rows)


_GATE_SWEPT: set[int] = set()


def collapse_gate_duplicates(port: int) -> None:
    """One-time housekeeping per worker session: the duplicates already staged
    by the pre-guard era collapse to the NEWEST copy per (kind, action,
    subject) — the older ones resolve done with an honest note. The worker
    tidies only its own re-staged duties; the human's asks are never touched."""
    if port in _GATE_SWEPT:
        return
    _GATE_SWEPT.add(port)
    try:
        rows = call(port, "GET", "/requests").get("requests", [])
    except Exception:
        _GATE_SWEPT.discard(port)
        return
    groups: dict[tuple, list] = {}
    for r in rows:
        if r.get("status") != "staged" or r.get("kind") not in ("mind", "service"):
            continue
        if r.get("action") not in ("reapprove",):
            continue
        key = (r["kind"], r.get("action"), r.get("mind") or r.get("name"))
        groups.setdefault(key, []).append(r)
    for key, dupes in groups.items():
        dupes.sort(key=lambda r: str(r.get("at", "")))
        for r in dupes[:-1]:                  # every copy but the newest
            try:
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "done",
                      "result": {"superseded": "a newer copy of this ask stands "
                                               "— collapsed by the gate's dedup"}})
            except Exception:
                pass
        if len(dupes) > 1:
            print(f"  ↳ gate tidied: {len(dupes) - 1} duplicate {key[0]} ask(s) "
                  f"for {key[2]} collapsed — the newest stands")


def wire_consents(port: int, scope: str) -> list[dict]:
    """The consent ledger from the wire (0034 §4): current head per worldline,
    read under the librarian's seat — revoked shown with its posture."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    rows = []
    for h in r.get("hits", []):
        if "consent" not in (h.get("tags") or []):
            continue
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        if isinstance(body, dict) and "consent" in body:
            rows.append({"id": h["ref"], "consent": body["consent"],
                         "derived_from": h.get("derived_from") or [],
                         "at": h.get("occurred_at", "")})
    rows.sort(key=lambda x: x["at"])
    return continuity.consent_heads(rows)


def _consent_head(port: int, scope: str, *, role: str | None = None,
                  modality: str | None = None) -> dict | None:
    for c in wire_consents(port, scope):
        if role and c.get("role") == role:
            return c
        if modality and modality in (c.get("modalities") or []):
            return c
    return None


def write_revocation(port: int, scope: str, *, role: str | None = None,
                     modality: str | None = None, reason: str = "") -> str:
    """Revocation acts NOW (0034 §4): stopping access — or recording — is safe
    and never waits at a gate. A standing head gets a revoked sibling; a
    modality with no head gets a fresh revoked worldline (the template's
    default consented recording, explicitly withdrawn). becky authors: consent
    is the door-keeper's ledger."""
    me = {"did": _BECKY.did, "scope": scope}
    head = _consent_head(port, scope, role=role, modality=modality)
    if head is not None:
        rec = make_memory(me, _BECKY.kp, scope,
                          continuity.revoke_body(head, reason), kind="semantic",
                          tags=["consent",
                                continuity.consent_key({k: v for k, v in head.items()
                                                        if k != "id"})])
        rec["derived_from"] = [head["id"]]
    elif modality is not None:
        rec = continuity.make_consent(me, _BECKY.kp, scope, purpose=reason or
                                      "the human said stop",
                                      modalities=[modality], posture="revoked")
    else:
        return f"no {role} access stands — nothing to revoke"
    try:
        call(port, "POST", "/records", rec)
    except Exception as e:
        return f"the revocation stumbled: {e}"
    what = role and f"{role} access" or f"{modality} recording"
    print(f"  ↳ consent REVOKED on {scope}: {what} — immediate, on the worldline")
    return f"{what} revoked — immediate, on the record"


def on_consent(port: int, scope: str, r: dict, *, approved: bool = False,
               declined: bool = False) -> None:
    """0034 §4 at the gate: GRANTING access to a person's memory — or resuming
    a recording — is a consequence; the ask stages with its bundle readable,
    and only the human's word mints the consent record (0012). becky signs:
    she keeps every door."""
    if r.get("bell"):                         # the bell's grant (0044 sp2)
        on_bell_consent(port, scope, r, approved=approved, declined=declined)
        return
    role = r.get("role") or None
    modality = r.get("modality") or None
    purpose = str(r.get("purpose") or "")
    days = int(r.get("days") or 30)
    me = {"did": _BECKY.did, "scope": scope}
    if declined:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"declined": True,
                         "reply": "declined — no access opens, and the record "
                                  "keeps that you chose"}})
        print(f"  ↳ consent declined at the gate ({role or modality})")
        return
    if approved:
        rec = continuity.make_consent(me, _BECKY.kp, scope, purpose=purpose,
                                      role=role, holder=str(r.get("holder") or ""),
                                      modalities=[modality] if modality else None,
                                      window_days=days,
                                      approved_ref=str(r.get("id") or ""))
        head = _consent_head(port, scope, role=role, modality=modality)
        if head is not None:                  # one worldline per subject (0032's idiom)
            rec["derived_from"] = [head["id"]]
        call(port, "POST", "/records", rec)
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"consent": rec["id"],
                         "reply": f"opened on your word — "
                                  f"{role or modality}, a {days}-day window"}})
        print(f"  ↳ consent OPENED: {role or modality} — {rec['id'][:18]}…")
        return
    b = continuity.ROLE_BUNDLES.get(role or "", {})
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "staged",
          "result": {"held": "access to a person's memory is a consequence — "
                             "open or decline at the gate (0034 §4)",
                     "terms": (f"{role}: {' · '.join(b.get('domains', []))} — "
                               f"{b.get('note', '')} · {days}-day window"
                               if role else
                               f"resume {modality} recording · {days}-day window")
                     + " · the sealed never delegates"}})
    print(f"  ↳ consent ask staged ({role or modality}) — the gate waits")


def wire_testaments(port: int, scope: str) -> list[dict]:
    """The last standing word from the wire (0035 §2): the testament
    worldline's head, read under the librarian's seat — revoked shown with
    its posture, because a withdrawn word is a state, never an absence."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    rows = []
    for h in r.get("hits", []):
        if "testament" not in (h.get("tags") or []):
            continue
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        if isinstance(body, dict) and "testament" in body:
            rows.append({"id": h["ref"], "testament": body["testament"],
                         "derived_from": h.get("derived_from") or [],
                         "at": h.get("occurred_at", "")})
    rows.sort(key=lambda x: x["at"])
    return continuity.testament_heads(rows)


def write_testament_revocation(port: int, scope: str) -> str:
    """Revocation acts NOW (0035 §2): withdrawing a future consequence is safe
    and never waits at a gate. The standing head gets a revoked sibling —
    without a standing word, every domain seals (§8 lock 2). becky authors:
    the testament is the door-keeper's ledger."""
    heads = [h for h in wire_testaments(port, scope)
             if h.get("posture") == "standing"]
    if not heads:
        return "no testament stands — nothing to revoke; every domain seals"
    head = heads[-1]
    rec = make_memory({"did": _BECKY.did, "scope": scope}, _BECKY.kp, scope,
                      continuity.revoke_testament_body(head), kind="semantic",
                      tags=["testament"])
    rec["derived_from"] = [head["id"]]
    try:
        call(port, "POST", "/records", rec)
    except Exception as e:
        return f"the revocation stumbled: {e}"
    print(f"  ↳ testament REVOKED on {scope} — immediate, on the worldline")
    return ("your testament is revoked — immediate, on the record; every "
            "domain seals until you speak again")


def on_testament(port: int, scope: str, r: dict, *, approved: bool = False,
                 declined: bool = False) -> None:
    """0035 §2 at the gate: writing a testament ARMS future consequence — the
    ask stages with its fates readable, and only the human's word mints the
    standing record (0012). becky signs: she keeps every door, this one
    included."""
    fates = {str(k): str(v) for k, v in (r.get("fates") or {}).items()}
    executor = str(r.get("executor") or "")
    heir = str(r.get("heir") or "")
    witnesses = [str(w) for w in r.get("witnesses") or []]
    silence_days = int(r.get("silence_days") or 30)
    me = {"did": _BECKY.did, "scope": scope}
    if declined:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"declined": True,
                         "reply": "declined — no word stands, every domain "
                                  "seals, and the record keeps that you chose"}})
        print("  ↳ testament declined at the gate")
        return
    if approved:
        try:
            rec = continuity.make_testament(me, _BECKY.kp, scope, fates=fates,
                                            executor=executor, heir=heir,
                                            witnesses=witnesses,
                                            silence_days=silence_days,
                                            approved_ref=str(r.get("id") or ""))
        except ValueError as e:              # the §8 locks refuse at mint, loudly
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "done",
                  "result": {"refused": str(e)}})
            print(f"  ↳ testament REFUSED at mint: {e}")
            return
        heads = [h for h in wire_testaments(port, scope)
                 if h.get("posture") == "standing"]
        if heads:                             # one worldline per human (0032's idiom)
            rec["derived_from"] = [heads[-1]["id"]]
        call(port, "POST", "/records", rec)
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"testament": rec["id"],
                         "reply": "your testament stands on your word — "
                                  "revocable to your last day"}})
        print(f"  ↳ testament STANDS: {rec['id'][:18]}…")
        return
    fates_words = " · ".join(f"{d} {f}" for d, f in fates.items()) or "no fates"
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "staged",
          "result": {"held": "the last standing word arms future consequence "
                             "— speak or decline at the gate (0035 §2)",
                     "terms": f"{fates_words} · unnamed domains seal"
                              + (f" · executor {executor}" if executor else "")
                              + (f" · heir {heir}" if heir else "")
                              + (f" · witness {', '.join(witnesses)}"
                                 if witnesses else "")
                              + f" · {silence_days}-day silence window · "
                                "silence may only contain; only attested "
                                "death executes"}})
    print("  ↳ testament staged — the gate waits")


# ---------------------------------------------------------------- the passage (0035 §3)

_PASSAGE_LAST = 0.0
PASSAGE_EVERY = int(os.environ.get("ORRETH_PASSAGE_EVERY", "60"))
# a testament-day in seconds — a RIG dial for proving the machine, never law
SILENCE_UNIT = int(os.environ.get("ORRETH_SILENCE_UNIT", "86400"))

# death-administration asks are not heartbeats — v0 honesty: the executor
# speaks through the same glass until 0012's signer registry lands, so the
# passage's own administration must not read as its human returning
_NOT_A_HEARTBEAT = ("attest death", "abort the attestation",
                    "abort attestation", "show the passage", "show passage")


def wire_passage(port: int, scope: str) -> list[dict]:
    """The passage worldline from the wire (0035 §3): every transition kept,
    the head ruling — the machine is legible forever."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    rows = []
    for h in r.get("hits", []):
        if "passage" not in (h.get("tags") or []):
            continue
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        if isinstance(body, dict) and "passage" in body:
            rows.append({"id": h["ref"], "passage": body["passage"],
                         "derived_from": h.get("derived_from") or [],
                         "at": h.get("occurred_at", "")})
    rows.sort(key=lambda x: x["at"])
    return continuity.passage_heads(rows)


# silence must be OBSERVED, never inferred: the watch floors its verdict at
# its own boot (a watcher that just woke has watched nothing), and the worker
# stamps its own hand each time it answers a living human — the ranked
# retrieve is the recover-after-restart source, never the primary signal.
_WATCH_BOOT = time.time()
_HUMAN_HAND: dict[str, float] = {}
# floors whose walk has completed: the organs REST there — a legacy universe
# doesn't dream, it keeps (0035 §6; 0009's hibernation, final application).
# Repopulated by the passage sweep on restart.
_LEGACY_FLOORS: set[str] = set()


def _wall(ts: float) -> str:
    from datetime import datetime, timezone
    return datetime.fromtimestamp(ts, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def last_human_act(port: int, scope: str) -> str:
    """The heartbeat signal: the newest parlor exchange that is the HUMAN
    living in their universe — death-administration asks excluded, safer-mode
    exchanges never written (consent bounds this watch too) — floored at the
    watch's own boot and at the worker's first-hand record of answering."""
    acts = [a["at"] for a in wire_audiences(port, scope)
            if not str(a.get("asked") or "").strip().lower()
            .startswith(_NOT_A_HEARTBEAT)]
    acts.append(_wall(_WATCH_BOOT))
    if scope in _HUMAN_HAND:
        acts.append(_wall(_HUMAN_HAND[scope]))
    return max(acts)


# the beat's own hand, per scope: (state, wall-clock, record id) — the ranked
# retrieve can trail a fresh write, and a machine that trusts a stale mirror
# repeats itself (the 0032 re-staging dedup lesson, third organ to learn it).
# Worker-local and lost on restart: one transient duplicate pair after a
# restart is the honest cost, and the record keeps it. A dedicated tag-indexed
# read is the queued improvement.
_PASSAGE_HAND: dict[str, tuple[str, float, str]] = {}


def write_passage(port: int, scope: str, state: str, reason: str, *,
                  evidence: list | None = None, attestors: list | None = None,
                  cooling_until: str = "", prev: dict | None = None) -> dict:
    """One transition, becky-signed, deriving from the head it supersedes."""
    me = {"did": _BECKY.did, "scope": scope}
    rec = continuity.make_passage(me, _BECKY.kp, scope, state, reason=reason,
                                  evidence=evidence, attestors=attestors,
                                  cooling_until=cooling_until)
    if prev is not None:
        rec["derived_from"] = [prev["id"]]
    call(port, "POST", "/records", rec)
    _PASSAGE_HAND[scope] = (state, time.time(), rec["id"])
    print(f"  ↳ the passage: {scope} → {state.upper()} — {reason}")
    return {"id": rec["id"], **json.loads(crypto._b64d(rec["body"]).decode())["passage"]}


def passage_now(port: int, scope: str) -> tuple[str, dict | None]:
    """The machine's current state and head: the wire's word, corrected by
    our own hand when the index trails a fresh write — every door consults
    THIS, so no gate is ever refused (or opened) by a stale mirror."""
    heads = wire_passage(port, scope)
    head = heads[-1] if heads else None
    state = continuity.passage_state(head)
    hand = _PASSAGE_HAND.get(scope)
    if hand and hand[0] != state and time.time() - hand[1] < 300:
        return hand[0], {"id": hand[2], "state": hand[0]}
    return state, head


def _post_reachout(port: int) -> None:
    """One question, one card (the 0032 dedup idiom): a reach-out already
    pending is never doubled, however many beats pass unanswered."""
    try:
        rows = call(port, "GET", "/requests").get("requests", [])
    except Exception:
        rows = []
    if any(r.get("kind") == "passage" and r.get("status") == "pending"
           for r in rows):
        return
    call(port, "POST", "/requests",
         {"kind": "passage",
          "text": "the universe reached out — silence past your window; "
                  "a word from you answers (0035 §3)"})


def _resolve_reachouts(port: int, reply: str) -> None:
    """The reach-out was answered: every pending passage ask closes with the
    honest sentence — nothing was lost."""
    try:
        rows = call(port, "GET", "/requests").get("requests", [])
    except Exception:
        return
    for r in rows:
        if r.get("kind") == "passage" and r.get("status") == "pending":
            try:
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "done",
                      "result": {"reply": reply}})
            except Exception:
                pass


def abort_attestation(port: int, scope: str) -> str:
    """One voice saves (0012 §3): an attested death returns to SEALED — the
    universe stays contained, and the record keeps that someone spoke."""
    state, head = passage_now(port, scope)
    if state != "attested":
        return "no attestation runs — nothing to abort"
    write_passage(port, scope, "sealed",
                  "an entitled voice aborted the attestation — one voice saves",
                  prev=head)
    return ("the attestation is aborted — the universe returns to SEALED, "
            "contained and reversible; the record keeps that you spoke")


def passage_beat() -> None:
    """The silence watch (0035 §3), one sweep per round across every floor
    with a standing testament: silence may only CONTAIN — reach out at the
    window, seal at twice the window, and never more. A heartbeat reverses
    everything reversible. Detection stages, never decides (0013 §3)."""
    global _PASSAGE_LAST
    if time.time() - _PASSAGE_LAST < PASSAGE_EVERY:
        return
    _PASSAGE_LAST = time.time()              # set early — a failing beat never hot-loops
    for p, s in sorted(FLOOR_SCOPES.items()):
        try:
            _passage_floor(p, s)
        except Exception as e:
            print(f"    (the passage watch stumbled at {s}: {e})")


def _passage_floor(port: int, scope: str) -> None:
    tst = [h for h in wire_testaments(port, scope)
           if h.get("posture") == "standing"]
    if not tst:
        return                                # no standing word — nothing watches
    state, head = passage_now(port, scope)
    if state in ("executed", "legacy"):
        if scope not in _LEGACY_FLOORS:       # the organs rest here (0035 §6)
            _LEGACY_FLOORS.add(scope)
            _mark_legacy(port)                # the glass's signal, healed
        return                                # a closed worldline never reopens
    days = int((tst[-1].get("silence_window") or {}).get("days", 30))
    verdict = continuity.silence_verdict(days, last_human_act(port, scope),
                                         NOW(), unit_secs=SILENCE_UNIT)
    if state == "attested":
        if verdict == "living":               # the loudest abort is a heartbeat
            write_passage(port, scope, "living",
                          "a heartbeat aborted the attestation — the loudest "
                          "abort; the seal lifts, nothing was lost", prev=head)
            _resolve_reachouts(port, "a heartbeat answered — the human "
                                     "returned; the attestation is aborted")
            return
        until = str((head or {}).get("cooling_until") or "")
        if until and until <= NOW():          # passed in silence — the walk (0035 §4)
            execute_estate(port, scope, tst[-1], head)
        return
    if verdict == "living":
        if state in ("unresponsive", "sealed"):
            write_passage(port, scope, "living",
                          "a heartbeat answered — the seal lifts, nothing "
                          "was lost", prev=head)
            _resolve_reachouts(port, "a heartbeat answered — the human "
                                     "returned; the seal lifts, nothing was lost")
        return
    if verdict == "unresponsive" and state == "living":
        head = write_passage(port, scope, "unresponsive",
                             "silence past the window — the seats ask after "
                             "their human", prev=head)
        _post_reachout(port)
        return
    if verdict == "sealed" and state in ("living", "unresponsive"):
        if state == "living":                 # the machine takes no shortcuts
            head = write_passage(port, scope, "unresponsive",
                                 "silence past the window — the seats ask "
                                 "after their human", prev=head)
            _post_reachout(port)
        write_passage(port, scope, "sealed",
                      "still silent — contained at machine speed, "
                      "reversible, loud; one heartbeat unseals", prev=head)


def _domain_refs(port: int, scope: str, domain: str) -> list[str]:
    """Every record wearing the domain's tag — what a domain's fate walks
    over. Rides the same ranked read as the rest of the wire (the queued
    tag-indexed improvement applies here above all)."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=3650)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    return [h["ref"] for h in r.get("hits", [])
            if domain in (h.get("tags") or [])]


def execute_estate(port: int, scope: str, tst: dict, head: dict) -> None:
    """The fates walk (0035 §4): the cooling-off passed in silence, so the
    machine crosses its one irreversible line — domain by domain, every step
    an estate record, becky-signed, legible forever. Seal stands; custody
    springs (the grant is consulted at becky's door — sp4's parlor); the
    governed shred goes through 0026's tombstone door and the stubs survive;
    key mortality needs no door at all. Then LEGACY: the universe keeps."""
    head = write_passage(port, scope, "executed",
                         "the cooling-off passed in silence — the fates walk",
                         prev=head)
    me = {"did": _BECKY.did, "scope": scope}
    for step in continuity.execution_walk(tst):
        fate, domain = step["fate"], step["domain"]
        if step.get("held"):
            outcome = ("the shred order queues behind the legal hold — "
                       "it does not die (0004)")
        elif fate == "shred" and step.get("method") == "key-mortality":
            outcome = ("shredded by key mortality — the keys died with "
                       "their keeper; no door needed to open")
        elif fate == "shred":
            refs = _domain_refs(port, scope, domain)
            n = sum(1 for ref in refs
                    if shred_claim(port, ref,
                                   f"the testament's word: {domain} shreds"))
            outcome = (f"{n} record(s) through the tombstone door — "
                       "the stubs survive; the estate can prove what it "
                       "destroyed (0026)")
        elif fate == "pass":
            terms = continuity.succession_terms(tst, "executed", scope)
            outcome = (f"custody springs for {terms['holder']} — retrieve + "
                       "graft rights over " + ", ".join(terms["domains"])
                       + "; never govern, never the keys, never the voice"
                       if terms else "custody had no hands — sealed instead")
        else:
            outcome = step.get("note",
                               "sealed standing — reads only through the "
                               "survivors' door")
        rec = make_memory(me, _BECKY.kp, scope,
                          {"estate": {**step, "outcome": outcome}},
                          kind="semantic", tags=["estate"])
        try:
            call(port, "POST", "/records", rec)
        except Exception as e:
            print(f"    (an estate step stumbled at {domain}: {e})")
        print(f"  ↳ the estate: {domain} → {fate} — {outcome}")
    write_passage(port, scope, "legacy",
                  "the walk is complete — the universe keeps", prev=head)
    _LEGACY_FLOORS.add(scope)
    _mark_legacy(port)


def _mark_legacy(port: int) -> None:
    """The glass's quiet signal (0035 §6), healed idempotently: a legacy
    floor always carries one settled `legacy` request — the console reads
    requests every breath, so the brain cools to a constellation and the
    header learns the state. The record of truth stays the passage worldline;
    this is a mirror of it, never a second truth."""
    try:
        rows = call(port, "GET", "/requests").get("requests", [])
    except Exception:
        return
    if not any(r.get("kind") == "legacy" for r in rows):
        try:
            call(port, "POST", "/requests",
                 {"kind": "legacy",
                  "text": "the universe keeps — legacy; the archive speaks "
                          "about, never as (0035 §6)"})
            rows = call(port, "GET", "/requests").get("requests", [])
        except Exception:
            return
    for r in rows:
        if r.get("kind") == "legacy" and r.get("status") == "pending":
            try:
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "done",
                      "result": {"reply": "the walk is complete — the "
                                          "universe keeps"}})
            except Exception:
                pass


def on_attestation(port: int, scope: str, r: dict, *, approved: bool = False,
                   declined: bool = False) -> None:
    """0035 §3 at the gravest gate: the ask stages with its evidence and
    roster readable; approval only STARTS the cooling-off — approved-but-held
    (0012 §3) — and the guards re-check at the door, because this gate above
    all must never be right by accident."""
    evidence = [str(e) for e in r.get("evidence") or []]
    attestors = [str(a) for a in r.get("attestors") or []]
    registry = bool(r.get("registry"))
    if declined:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"declined": True,
                         "reply": "declined — the universe stays sealed, and "
                                  "the record keeps that you chose"}})
        print("  ↳ attestation declined at the gate — the universe stays sealed")
        return
    tst = [h for h in wire_testaments(port, scope)
           if h.get("posture") == "standing"]
    state, head = passage_now(port, scope)
    if approved:
        if not tst or not continuity.may_stage_attestation({"state": state}) \
                or not continuity.attestation_met(tst[-1], attestors, evidence,
                                                  registry=registry):
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "done",
                  "result": {"refused": "the bar is no longer met — the "
                                        "universe must be SEALED and quorum 2 "
                                        "must stand against the testament's "
                                        "roster (0035 §8)"}})
            print("  ↳ attestation REFUSED at the door — the bar moved")
            return
        from datetime import datetime, timedelta, timezone
        until = (datetime.now(timezone.utc)
                 + timedelta(seconds=continuity.ATTESTATION_COOLING_DAYS
                             * SILENCE_UNIT)).strftime("%Y-%m-%dT%H:%M:%SZ")
        write_passage(port, scope, "attested",
                      "death attested at the gate — quorum 2 against the "
                      "roster; the cooling-off runs",
                      evidence=evidence, attestors=attestors,
                      cooling_until=until, prev=head)
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"reply": f"attested — the cooling-off runs until "
                                  f"{until}. the universe stays contained; "
                                  "one voice returns it to sealed, a "
                                  "heartbeat to living (0035 §3)"}})
        print(f"  ↳ attestation STANDS — cooling until {until}")
        return
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "staged",
          "result": {"held": "a death at the gate — the gravest consequence "
                             "waits for you (0035 §3)",
                     "terms": "evidence " + (", ".join(evidence) or "none")
                              + " · attestors " + (", ".join(attestors) or "none")
                              + (" · registry evidence" if registry else "")
                              + f" · approval starts a "
                                f"{continuity.ATTESTATION_COOLING_DAYS}-day "
                                "cooling-off — any entitled voice aborts; a "
                                "heartbeat aborts everything"}})
    print("  ↳ attestation staged — the gravest gate waits")


# ---------------------------------------------------------------- the meaning axis (0022 Phase 2)

EMBED_PORT = int(os.environ.get("ORRETH_EMBED_PORT", "4562"))
_EMBED_LAST = 0.0
EMBED_EVERY = int(os.environ.get("ORRETH_EMBED_EVERY", "90"))


def embed_door() -> None:
    """The node machine's local embedder (0022 §10, bytes-local at machine
    granularity on the dev rig — the in-process fastembed-rs landing is the
    named production step). Bound wide so the container bridge can reach it;
    it embeds text and holds nothing — no record ever passes through it."""
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

    class H(BaseHTTPRequestHandler):
        def do_POST(self):
            ln = int(self.headers.get("content-length") or 0)
            try:
                data = json.loads(self.rfile.read(ln) or b"{}")
                vecs = meaning.embed([str(t) for t in data.get("texts") or []]) or []
            except Exception:
                vecs = []
            out = json.dumps({"vectors": vecs}).encode()
            self.send_response(200)
            self.send_header("content-type", "application/json")
            self.end_headers()
            self.wfile.write(out)

        def do_GET(self):
            """The instrument room's supply door (0043 sp3) and the craft
            room's (0045 sp1): composed payloads, CORS-open so the glass on
            any floor's port can drink them — behind the worker's own door,
            the plane untouched (rule 9)."""
            route = self.path.split("?")[0]
            if route not in ("/observatory", "/governance"):
                self.send_response(404)
                self.end_headers()
                return
            try:
                out = json.dumps(compose_governance() if route == "/governance"
                                 else compose_observatory()).encode()
            except Exception as e:
                out = json.dumps({"error": str(e)[:120]}).encode()
            self.send_response(200)
            self.send_header("content-type", "application/json")
            self.send_header("access-control-allow-origin", "*")
            self.end_headers()
            self.wfile.write(out)

        def log_message(self, *a):              # the door is quiet
            pass

    try:
        ThreadingHTTPServer(("0.0.0.0", EMBED_PORT), H).serve_forever()
    except OSError as e:
        print(f"  (the embed door could not open on :{EMBED_PORT}: {e})")


def _body_text(body) -> str:
    """The string leaves of a record body, joined — what a record MEANS to the
    axis. Bounded; structure is the coordinate's job, not the vector's."""
    out: list[str] = []

    def walk(v):
        if isinstance(v, str):
            out.append(v)
        elif isinstance(v, dict):
            for x in v.values():
                walk(x)
        elif isinstance(v, list):
            for x in v:
                walk(x)
    walk(body)
    return " ".join(out)[:2000]


def embed_beat(port: int, scope: str) -> None:
    """The projection sweep (0022 §4): embed what the node accepted but the
    vector index lacks — computed HERE, where the bytes live, pushed through
    the becky-guarded door. A dark axis sweeps nothing; a bodyless record
    gets the NULL marker and is never revisited."""
    global _EMBED_LAST
    if time.time() - _EMBED_LAST < EMBED_EVERY:
        return
    _EMBED_LAST = time.time()                 # set early — a failing sweep never hot-loops
    if meaning.embedder() is None:
        return
    token = _ROOT.issue_token(_BECKY.did, "u:demo",
                              [{"action": "govern", "space": "self"}])
    try:
        missing = call(port, "POST", "/embeddings/missing",
                       {"token": token, "limit": 64}).get("missing", [])
    except Exception:
        return
    if not missing:
        return
    done = skipped = 0
    for rid in missing:
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(rid, safe='')}/body")
            text = _body_text(body).strip()
        except Exception:
            text = ""
        vec = (meaning.embed([text]) or [[]])[0] if text else []
        try:
            call(port, "POST", "/embeddings",
                 {"record_id": rid, "vector": vec, "token": token})
            done += 1 if vec else 0
            skipped += 0 if vec else 1
        except Exception:
            pass
    print(f"  ↳ the meaning axis: {scope} — {done} embedded"
          + (f" · {skipped} marked bodyless" if skipped else "")
          + f" ({len(missing)} swept)")


# ---------------------------------------------------------------- the Mirror (0034 sp3)

MIR = _seed("mirror")                 # the assessor — its own self, no seat, no voice
MIR_DID = crypto.did_key_for(MIR.public)
_MIRROR_LAST = 0.0
MIRROR_EVERY = int(os.environ.get("ORRETH_MIRROR_EVERY", "600"))


def wire_audiences(port: int, scope: str) -> list[dict]:
    """Every Human↔Resident exchange on this floor's record — what the Mirror
    may read. Exchanges answered under safer mode were never written; consent
    bounds the reflection (0034 §4)."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    out = []
    for h in r.get("hits", []):
        if "parlor" not in (h.get("tags") or []):
            continue
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        if isinstance(body, dict) and "parlor" in body:
            out.append({"ref": h["ref"], "resident": str(body.get("parlor") or "?"),
                        "asked": str(body.get("asked") or ""),
                        "reply": str(body.get("reply") or ""),
                        "author": h.get("author", ""),
                        "at": h.get("occurred_at", "")})
    out.sort(key=lambda x: x["at"])
    return out


def wire_interop(port: int, scope: str) -> list[dict]:
    """The interoperability ledger from the wire: current head per resident."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    rows = []
    for h in r.get("hits", []):
        if "mirror" not in (h.get("tags") or []):
            continue
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        if isinstance(body, dict) and "interop" in body:
            rows.append({"id": h["ref"], "interop": body["interop"],
                         "derived_from": h.get("derived_from") or [],
                         "at": h.get("occurred_at", "")})
    rows.sort(key=lambda x: x["at"])
    return mirror.interop_heads(rows)


def mirror_beat() -> None:
    """The Mirror's standing duty (0034 sp3), one reflection per round across
    every floor in reach: read the audiences since the last reflection, sort
    them (identity, never meaning), and write BOTH sides — profile
    observations (untrusted, evidenced, 0025) and friction onto grace's shelf
    (0031 §4) — with the interop ledger as the receipt. Assessor ≠ assessed
    (0005): the Mirror authors everything and is the subject of nothing."""
    global _MIRROR_LAST
    if time.time() - _MIRROR_LAST < MIRROR_EVERY:
        return
    _MIRROR_LAST = time.time()               # set early — a failing beat never hot-loops
    for p, s in sorted(FLOOR_SCOPES.items()):
        try:
            _mirror_floor(p, s)
        except Exception as e:
            print(f"    (the mirror clouded at {s}: {e})")


def _mirror_floor(port: int, scope: str) -> None:
    if scope in _LEGACY_FLOORS:
        return                                # the Mirror never assesses the dead (0035 §5)
    audiences = wire_audiences(port, scope)
    if not audiences:
        return
    heads = {h.get("resident"): h for h in wire_interop(port, scope)}
    known = {str(c.get("claim", "")) for _, c in profile_claims(port, scope)
             if c.get("asserted_by") == "mirror"}
    me = {"did": MIR_DID, "scope": scope}
    residents = sorted({a["resident"] for a in audiences})
    for name in residents:
        prev = heads.get(name)
        since = str((prev or {}).get("window", {}).get("to", ""))
        mine = [a for a in audiences if a["resident"] == name]
        if not any(a["at"] > since for a in mine):
            continue                          # nothing new to reflect for this seat
        # the relationship is CUMULATIVE — the sweep re-reads the whole story,
        # so a question repeated across sweeps is still a repeat; the watermark
        # only decides whether a new sibling is owed
        # the meaning axis (0022 Phase 2): differently-worded asks that mean
        # the same thing are one ask — local ONNX, bytes never leave (§10);
        # a dark axis degrades to identity inside assess, honestly
        stats = mirror.assess(mine, mirror_did=MIR_DID,
                              meaning=meaning).get(name)
        if not stats:
            continue
        window = {"from": mine[0]["at"], "to": mine[-1]["at"]}
        rec = mirror.make_interop(me, MIR, scope, name, stats, window=window,
                                  prev=(prev or {}).get("id"))
        try:
            call(port, "POST", "/records", rec)
        except Exception as e:
            print(f"    (interop write failed: {e})")
            continue
        for words in mirror.observations(name, stats):
            if words in known:
                continue                      # an observation is made once
            obs = profile.make_claim(me, MIR, scope, words,
                                     asserted_by="mirror", inferred_from=rec["id"])
            try:
                call(port, "POST", "/records", obs)
                known.add(words)
            except Exception as e:
                print(f"    (mirror observation write failed: {e})")
        note = mirror.friction_note(name, stats)
        if note and len(stats["friction"]) <= int((prev or {}).get("friction", 0)):
            note = None                       # friction files only when it GROWS
        if note:
            u_port = universe_port(port)
            fb = make_memory({"did": MIR_DID, "scope": UNIVERSE_SCOPE}, MIR,
                             UNIVERSE_SCOPE,
                             {"feedback": {"asset": f"parlor-{name}",
                                           "quoted": note, "by": "mirror"}},
                             kind="semantic",
                             tags=["asset-feedback", f"parlor-{name}"])
            fb["derived_from"] = [rec["id"]]
            try:
                call(u_port, "POST", "/records", fb)
            except Exception as e:
                print(f"    (mirror friction write failed: {e})")
        print(f"  ↳ the mirror reflects at {scope}: {name} — "
              f"{stats['exchanges']} exchange(s), {len(stats['repeats'])} repeat(s), "
              f"{len(stats['friction'])} friction — both sides updated")


_CHARTERED: set[str] = set()          # scopes whose continuity charter stands


def continuity_charter(port: int, scope: str) -> None:
    """0034 §7 sp1: a floor born wearing the continuity template gets its
    CHARTER on the record — config-as-memory (R8): the vector, the regime, the
    label canon, legible to the glass and to every resident. Planted once; the
    wire is checked before writing, so restarts never double-charter."""
    if scope in _CHARTERED:
        return
    spec = SHIPYARD.ledger().get(str(port)) or {}
    if spec.get("template") != continuity.TEMPLATE:
        _CHARTERED.add(scope)                 # not a continuity floor — settled
        return
    from datetime import datetime, timedelta, timezone
    seat_kp, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return                                # the floor is still waking — next beat
    if any("continuity-charter" in (h.get("tags") or []) for h in r.get("hits", [])):
        _CHARTERED.add(scope)                 # the charter already stands
        return
    rec = continuity.make_charter({"did": seat_did, "scope": scope}, seat_kp, scope)
    try:
        call(port, "POST", "/records", rec)
        _CHARTERED.add(scope)
        print(f"  ↳ the continuity charter lands at {scope} — the floor's law is "
              f"on its own record ({rec['id'][:18]}…)")
    except Exception as e:
        print(f"    (continuity charter write failed: {e})")


# ---------------------------------------------------------------- the farm keeper (0018)

def ledger_path(scope: str) -> Path:
    nest = HOME / "farm" / scope.replace("/", "~")
    nest.mkdir(parents=True, exist_ok=True)
    return nest / "services.json"


def ledger_load(scope: str) -> dict:
    p = ledger_path(scope)
    return json.loads(p.read_text()) if p.exists() else {}


def ledger_save(scope: str, data: dict) -> None:
    ledger_path(scope).write_text(json.dumps(data, indent=1, sort_keys=True))


def probe(endpoint: str) -> bool:
    """Alive = the server ANSWERED (any HTTP status); dead = the wire went quiet."""
    try:
        urllib.request.urlopen(urllib.request.Request(endpoint, method="GET"), timeout=4)
        return True
    except urllib.error.HTTPError:
        return True
    except Exception:
        return False


def mcp_tools(endpoint: str) -> list | None:
    """Enumerate a streamable-HTTP MCP server's tools — the manifest we pin (0018 §1)."""
    session = None

    def rpc(body: dict):
        nonlocal session
        headers = {"Content-Type": "application/json",
                   "Accept": "application/json, text/event-stream"}
        if session:
            headers["Mcp-Session-Id"] = session
        req = urllib.request.Request(endpoint, method="POST",
                                     data=json.dumps(body).encode(), headers=headers)
        with urllib.request.urlopen(req, timeout=8) as r:
            session = r.headers.get("Mcp-Session-Id") or session
            raw = r.read().decode()
        for line in raw.splitlines():            # unwrap SSE framing if the server streams
            if line.startswith("data:"):
                raw = line[5:].strip()
                break
        return json.loads(raw) if raw else {}

    try:
        rpc({"jsonrpc": "2.0", "id": 1, "method": "initialize",
             "params": {"protocolVersion": "2025-03-26", "capabilities": {},
                        "clientInfo": {"name": "orreth-charlotte", "version": "0.1"}}})
        try:
            rpc({"jsonrpc": "2.0", "method": "notifications/initialized"})
        except Exception:
            pass
        tools = rpc({"jsonrpc": "2.0", "id": 2, "method": "tools/list", "params": {}})
        return sorted(
            [{"name": t["name"], "description": t.get("description", ""),
              "schema": t.get("inputSchema", {})} for t in tools["result"]["tools"]],
            key=lambda t: t["name"])
    except Exception:
        return None


def fetch_manifest(svc: dict) -> list | None:
    """MCP servers are enumerated live; declared manifests stand for plain HTTP tools."""
    if svc.get("kind") == "mcp":
        return mcp_tools(svc["endpoint"])
    return svc.get("manifest") or []


def service_did(req: dict) -> str:
    """Vendor-anchored did:web from the endpoint's domain (0014 §2); explicit did wins."""
    if req.get("did"):
        return req["did"]
    host = req.get("endpoint", "").split("//")[-1].split("/")[0].split(":")[0]
    if host and "." in host and not host.replace(".", "").isdigit():
        return f"did:web:{host.removeprefix('api.').removeprefix('mcp.')}"
    kp = crypto.KeyPair()                        # a local tool with no domain: cheap leaf
    return crypto.did_key_for(kp.public)


def worldline(port: int, scope: str, svc: dict, event: str, **extra) -> None:
    """Every lifecycle transition is a signed MemoryRecord — the identity tells the
    universe, in time (0018 §4). Charlotte authors; the service never self-attests."""
    body = {"service": svc["name"], "did": svc.get("did", ""), "event": event,
            "state": svc.get("state", ""), "manifest_hash": svc.get("manifest_hash", ""),
            "at": NOW(), **extra}
    rec = make_memory({"did": CHA_DID, "scope": scope}, CHA, scope, body,
                      kind="episodic", tags=["service", svc["name"]])
    try:
        call(port, "POST", "/records", rec)
    except Exception as e:
        print(f"    (worldline write failed: {e})")


class FarmKeeper:
    """Charlotte's round: verify staged plantings, attest approvals, heartbeat the
    toolshed, age silent leases out, guard the rug-pull door, replant after restarts."""

    def __init__(self) -> None:
        self.misses: dict[tuple[int, str], int] = {}
        self.last_beat = 0.0

    # ---- the queue: plant · decom · reapprove -----------------------------------------
    def on_service_request(self, port: int, scope: str, r: dict) -> bool:
        """Returns True when the request reached a resting state (done/denied)."""
        action, status, name = r.get("action", "plant"), r.get("status"), r.get("name", "")
        if status == "pending" and action in ("decom", "reapprove"):
            # nothing to probe — consequence waits for the human (0012)
            call(port, "POST", "/requests/resolve", {"id": r["id"], "status": "staged"})
            return False
        if status == "pending" and action == "plant":
            svc = {"name": name, "did": service_did(r), "kind": r.get("svc_kind", "http"),
                   "endpoint": r.get("endpoint", ""), "transport": r.get("transport", "rest"),
                   "manifest": r.get("manifest") or []}
            manifest = fetch_manifest(svc)
            alive = probe(svc["endpoint"]) if svc["endpoint"] else False
            svc["manifest"] = manifest or svc["manifest"]
            planted = call(port, "POST", "/farm/plant", svc)
            worldline(port, scope, planted, "planted",
                      probed={"alive": alive, "tools": len(svc["manifest"])})
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "staged",
                  "result": {"did": planted["did"], "manifest_hash": planted["manifest_hash"],
                             "alive": alive, "tools": len(svc["manifest"])}})
            print(f"  ↳ staged planting {name}: alive={alive}, "
                  f"{len(svc['manifest'])} tool(s), pinned {planted['manifest_hash'][:18]}…")
            return False
        if status == "approved":
            if action in ("plant", "reapprove"):
                op = "attest" if action == "plant" else "reapprove"
                farm = {s["name"]: s for s in call(port, "GET", "/farm")["services"]}
                manifest = farm.get(name, {}).get("manifest", [])
                svc = call(port, "POST", "/farm/state",
                           {"name": name, "op": op, "manifest": manifest})
                worldline(port, scope, svc, "attested" if op == "attest" else "re-attested")
                led = ledger_load(scope)
                led[name] = {k: svc[k] for k in ("name", "did", "kind", "endpoint",
                                                 "transport", "manifest", "manifest_hash")}
                ledger_save(scope, led)
                print(f"  ↳ attested {name} — probation begins (beats earn serving)")
            elif action == "decom":
                discredit = bool(r.get("discredit"))
                svc = call(port, "POST", "/farm/state",
                           {"name": name, "op": "decom",
                            "reason": r.get("reason", ""), "discredit": discredit})
                worldline(port, scope, svc, "decommissioned",
                          reason=r.get("reason", ""), discredit=discredit)
                if discredit:
                    # separation of duties: charlotte discredits the SOURCE; the
                    # KNOWLEDGE recall is the librarian's walk (0014 §4). The handoff
                    # rides the queue — visible, auditable, no second gate (the human
                    # already approved the discredit).
                    worldline(port, scope, svc, "discredited",
                              note="recall handed to the librarian (0014 §4)")
                    call(port, "POST", "/requests",
                         {"kind": "recall", "source_did": svc.get("did", ""),
                          "service": name,
                          "reason": r.get("reason", "") or "source discredited",
                          "text": f"recall knowledge from discredited {name}"})
                led = ledger_load(scope)
                led.pop(name, None)
                ledger_save(scope, led)
                print(f"  ↳ decommissioned {name}" + (" · source discredited" if discredit else ""))
            call(port, "POST", "/requests/resolve", {"id": r["id"], "status": "done"})
            return True
        if status == "denied":
            try:
                svc = call(port, "POST", "/farm/state", {"name": name, "op": "decom",
                                                         "reason": "denied at the gate"})
                worldline(port, scope, svc, "denied")
            except Exception:
                pass
            # a denied service leaves the ledger too — replant must never resurrect
            # what a human refused (the ledger seeds only the approved)
            led = ledger_load(scope)
            led.pop(name, None)
            ledger_save(scope, led)
            call(port, "POST", "/requests/resolve", {"id": r["id"], "status": "done"})
            print(f"  ↳ denied {name} — never served")
            return True
        return False

    # ---- the round: heartbeats, drops, rejoins, replants -------------------------------
    def tend(self, port: int, scope: str) -> None:
        try:
            farm = call(port, "GET", "/farm")["services"]
        except Exception:
            return
        local = [s for s in farm if s.get("floor") == scope]
        self.replant(port, scope, {s["name"] for s in local})
        for svc in local:
            key, state = (port, svc["name"]), svc["state"]
            if state in ("probation", "serving"):
                if probe(svc["endpoint"]):
                    self.misses[key] = 0
                    beat = call(port, "POST", "/farm/hello", {"name": svc["name"]})
                    if beat.get("transition", {}).get("to") == "serving":
                        worldline(port, scope, beat, "serving",
                                  earned_after=beat.get("beats"))
                        print(f"  ↳ {svc['name']} earned its place — serving")
                else:
                    self.misses[key] = self.misses.get(key, 0) + 1
                    if self.misses[key] >= MISSES_TO_DROP:
                        dropped = call(port, "POST", "/farm/state",
                                       {"name": svc["name"], "op": "expire"})
                        worldline(port, scope, dropped, "dropped",
                                  reason=f"{self.misses[key]} missed heartbeats")
                        print(f"  ↳ {svc['name']} dropped — the lease aged out")
            elif state == "dropped" and probe(svc["endpoint"]):
                manifest = fetch_manifest(svc)
                if manifest is None:
                    continue                     # answered but not enumerable yet
                back = call(port, "POST", "/farm/state",
                            {"name": svc["name"], "op": "rejoin", "manifest": manifest})
                if back["state"] == "serving":
                    worldline(port, scope, back, "rejoined")
                    print(f"  ↳ {svc['name']} rejoined — same manifest, same self")
                else:                            # the rug-pull door (0018 §2)
                    worldline(port, scope, back, "manifest-changed",
                              pinned=back["manifest_hash"], seen=back.get("proposed_hash"))
                    if not open_ask(port, {"kind": "service", "action": "reapprove",
                                           "name": svc["name"]}):
                        call(port, "POST", "/requests",
                             {"kind": "service", "action": "reapprove", "name": svc["name"],
                              "proposed_hash": back.get("proposed_hash"),
                              "text": f"{svc['name']} came back CHANGED — re-approve its new manifest?"})
                    print(f"  ↳ {svc['name']} quarantined — its manifest changed while it was gone")
                    # trust wears a review date (0031 §5): a changed manifest is a
                    # freshness trigger — charlotte fires the signal, the librarian
                    # walks; the source is doubted, not damned (that gate is 0026's)
                    if svc.get("did"):
                        try:
                            note = revalidate_walk(
                                port, scope, svc["did"], "source-changed",
                                f"{svc['name']} came back changed — the pin caught it")
                            print(f"    ↳ {note}")
                        except Exception as e:
                            print(f"    (revalidation walk failed: {e})")

    def replant(self, port: int, scope: str, present: set) -> None:
        """The daemon may die; the toolshed doesn't. The ledger re-seeds live state,
        and the worldline shows the restart honestly."""
        for name, svc in ledger_load(scope).items():
            if name in present:
                continue
            try:
                call(port, "POST", "/farm/plant", svc)
                call(port, "POST", "/farm/state",
                     {"name": name, "op": "attest", "manifest": svc.get("manifest", [])})
                worldline(port, scope, svc, "replanted",
                          note="daemon restarted; approval is durable in the ledger")
                print(f"  ↳ replanted {name} after a daemon restart")
            except Exception as e:
                print(f"    (replant {name} failed: {e})")


KEEPER = FarmKeeper()


# ---------------------------------------------------------------- the wrangler (0019)

CATALOG_TTL = 300                            # seconds the market snapshot stays fresh
EOL_HORIZON_DAYS = 30                        # inside this window an expiry burns
MIND_DIDS = {"anthropic": "did:web:anthropic.com", "openai": "did:web:openai.com",
             "openrouter": "did:web:openrouter.ai", "google": "did:web:google.com",
             "mistralai": "did:web:mistral.ai"}


def stable_ledger_path(scope: str) -> Path:
    nest = HOME / "stable" / scope.replace("/", "~")
    nest.mkdir(parents=True, exist_ok=True)
    return nest / "minds.json"


def stable_ledger_load(scope: str) -> dict:
    p = stable_ledger_path(scope)
    return json.loads(p.read_text()) if p.exists() else {}


def stable_ledger_save(scope: str, data: dict) -> None:
    stable_ledger_path(scope).write_text(json.dumps(data, indent=1, sort_keys=True))


def openrouter_catalog() -> list[dict]:
    """The market, read freely: OpenRouter's public list is INTEL for every stall,
    whatever route carries the call (0019 §1). Routing stays LiteLLM-direct on the
    floor's own keys by default. Cached on disk; a stale snapshot beats none."""
    cache = HOME / "stable" / "catalog.json"
    cache.parent.mkdir(parents=True, exist_ok=True)
    if cache.exists() and time.time() - cache.stat().st_mtime < CATALOG_TTL:
        return json.loads(cache.read_text())
    try:
        raw = json.loads(urllib.request.urlopen(urllib.request.Request(
            "https://openrouter.ai/api/v1/models"), timeout=15).read())
        cat = [{"id": m["id"], "provider": m["id"].split("/")[0],
                "pricing": m.get("pricing", {}),
                "context_length": m.get("context_length"),
                "modalities": (m.get("architecture") or {}).get("input_modalities", []),
                "created": m.get("created"),
                "expires_at": m.get("expiration_date")}
               for m in raw.get("data", [])]
        cache.write_text(json.dumps(cat))
        return cat
    except Exception:
        return json.loads(cache.read_text()) if cache.exists() else []


def deal(entry: dict) -> dict:
    """The manifest ada pins: the DEAL, not the name — pricing, context, modalities.
    Any byte of it moving under the pin is drift, and drift walks the rug-pull door."""
    return {"pricing": entry.get("pricing", {}),
            "context_length": entry.get("context_length"),
            "modalities": entry.get("modalities", [])}


def mind_did(provider: str) -> str:
    return MIND_DIDS.get(provider, f"did:web:{provider}")


def mindline(port: int, scope: str, stall: dict, event: str, **extra) -> None:
    """Every lifecycle transition is a signed MemoryRecord — the stall's worldline.
    Ada authors; the model (and its provider) never self-attests."""
    body = {"mind": stall.get("id", ""), "did": stall.get("did", ""), "event": event,
            "state": stall.get("state", ""), "manifest_hash": stall.get("manifest_hash", ""),
            "at": NOW(), **extra}
    rec = make_memory({"did": ADA_DID, "scope": scope}, ADA, scope, body,
                      kind="episodic", tags=["mind", stall.get("id", "")])
    try:
        call(port, "POST", "/records", rec)
    except Exception as e:
        print(f"    (mindline write failed: {e})")


def recommend(old: dict, stalls: list, catalog: list) -> dict | None:
    """The replacement pick: a stall already serving the class wins outright; else
    catalog entries that can HOLD THE DEAL (context ≥ the pin's, modalities covering
    it) rank by price distance then recency — a cheaper mind that can't fit the work
    is no replacement, and never the next casualty (0019 §7, fit added 2026-07-08)."""
    for s in stalls:
        if s["id"] != old["id"] and s.get("class") == old.get("class") \
                and s.get("state") == "available":
            return {"id": s["id"], "why": "already serving this class", "in_stable": True}
    man = old.get("manifest") or {}
    old_p = float(man.get("pricing", {}).get("prompt") or 0)
    live = [c for c in catalog if c["id"] != old["id"] and not c.get("expires_at")]
    if not live:
        return None
    need_ctx = man.get("context_length") or 0
    need_mods = set(man.get("modalities") or [])
    fit = [c for c in live if (c.get("context_length") or 0) >= need_ctx
           and need_mods <= set(c.get("modalities") or [])]
    pool, why = (fit, "fits the deal — nearest price, newest catalog entry") if fit \
        else (live, "no full fit in the catalog — nearest price, newest")
    best = min(pool, key=lambda c: (
        abs(float((c.get("pricing") or {}).get("prompt") or 0) - old_p),
        -(c.get("created") or 0)))
    return {"id": best["id"], "provider": best.get("provider", ""),
            "why": why, "in_stable": False,
            "pricing": best.get("pricing", {}),
            "context_length": best.get("context_length"),
            "modalities": best.get("modalities", []), "created": best.get("created")}


class FlightBook:
    """0043 sp1, the flight recorder's wire twin: every governed thought the
    worker fires — canary, working thought, or the parlor's voice — lands one
    row here beside the plane's meter. Latency and the refusal taxonomy are the
    worker's own clock and book (instrument readings, never testimony; outside,
    refusal keeps its one face — rule 4); tokens and dollars remain log-truth,
    rebuildable from the daemon's signed meter. The book seeds from
    ~/.orreth/observatory/flight.jsonl like charlotte's ledger and AGES by the
    series' declared hourly horizon — even the monitoring ages honestly."""

    HOME = os.path.expanduser("~/.orreth/observatory")

    def __init__(self) -> None:
        self.call_log: list[dict] = []
        self.recorder = observatory.FlightRecorder()
        self.last_beat: str | None = None    # G1: the watcher's own pulse
        self._sealed_count = 0               # G2: persist when a new hour seals

    def _land(self, row: dict) -> None:
        self.call_log.append(row)
        try:
            os.makedirs(self.HOME, exist_ok=True)
            with open(os.path.join(self.HOME, "flight.jsonl"), "a") as f:
                f.write(json.dumps(row, sort_keys=True) + "\n")
        except Exception:
            pass                          # the book is an instrument, never a gate

    def note(self, *, caller: str, klass: str, model: str, tokens: int,
             usd: float, ms: int) -> None:
        self._land({"caller": caller, "class": klass, "model": model,
                    "tokens": tokens, "usd": round(usd, 6), "ms": ms,
                    "at": NOW()})

    def refuse(self, caller: str, klass: str, taxon: str) -> None:
        self._land({"refusal": taxon, "caller": caller, "class": klass,
                    "at": NOW()})

    def _persist_summaries(self) -> None:
        """G2 (0043 sp5): the distilled tiers outlive the process — the dump
        lands beside the book, and the book COMPACTS to its unsealed rows
        (what a sealed hour holds, the summary now holds; the raw row was
        redundant with its own distillate)."""
        s = self.recorder.series
        try:
            os.makedirs(self.HOME, exist_ok=True)
            with open(os.path.join(self.HOME, "summaries.json"), "w") as f:
                json.dump(s.dump(), f)
            su = s.sealed_until()
            if su:
                kept = [r for r in self.call_log if r.get("at", "") >= su]
                if len(kept) < len(self.call_log):
                    self.call_log = kept
                    self.recorder._cursor[(id(self), "calls")] = len(kept)
                    with open(os.path.join(self.HOME, "flight.jsonl"), "w") as f:
                        for row in kept:
                            f.write(json.dumps(row, sort_keys=True) + "\n")
        except Exception:
            pass                          # the book is an instrument, never a gate

    def replant(self) -> None:
        """The ledger seeds, the worker holds live state: the distilled tiers
        reload whole (G2), then the book's rows re-ingest — only what stands
        ABOVE the sealed horizon and inside the declared retention; what has
        aged or already distilled leaves the book. The compaction IS the
        retention law, applied to the recorder's own file."""
        try:
            with open(os.path.join(self.HOME, "summaries.json")) as f:
                self.recorder.series = observatory.Series.load(json.load(f))
        except Exception:
            pass
        path = os.path.join(self.HOME, "flight.jsonl")
        if not os.path.exists(path):
            return
        from datetime import datetime, timedelta, timezone
        horizon = self.recorder.series.retention["hourly"]
        floor_at = (datetime.now(timezone.utc)
                    - timedelta(seconds=horizon)).strftime("%Y-%m-%dT%H:%M:%SZ")
        floor_at = max(floor_at, self.recorder.series.sealed_until() or "")
        kept = []
        try:
            with open(path) as f:
                for line in f:
                    try:
                        row = json.loads(line)
                    except Exception:
                        continue
                    if row.get("at", "") >= floor_at:
                        kept.append(row)
            self.call_log = kept
            with open(path, "w") as f:
                for row in kept:
                    f.write(json.dumps(row, sort_keys=True) + "\n")
        except Exception:
            pass

    def beat(self) -> None:
        """Sweep fresh rows into the series and distill — the Observatory's
        pulse. Quiet when nothing new flew. A new sealed hour persists the
        pyramid (G2); a backdated row is refused, never fatal."""
        self.last_beat = NOW()
        try:
            n = self.recorder.sweep(now=self.last_beat, gateways=[self])
        except observatory.BackdatedReading as e:
            print(f"  🔭 the book held a backdated row — refused, "
                  f"the monotone law holds: {e}")
            return
        s = self.recorder.series
        sealed = sum(len(by) for by in s.hourly.values())
        if sealed != self._sealed_count:
            self._sealed_count = sealed
            self._persist_summaries()
        if n:
            thoughts = len(s.read("plane.thoughts")["points"]) + int(sum(
                p["count"] for p in
                s.read("plane.thoughts", resolution="hourly")["points"]))
            refusals = len(s.read("plane.refusals")["points"]) + int(sum(
                p["count"] for p in
                s.read("plane.refusals", resolution="hourly")["points"]))
            print(f"  🔭 flight recorder: {n} fresh reading(s) — "
                  f"{thoughts} thought(s), {refusals} refusal(s) on the book")


FLIGHT = FlightBook()


def governed_ping(port: int, mid: str, klass: str) -> dict | None:
    """One tiny real thought through ada's OWN gateway — authorize, call, meter, all
    under her DID, PINNED to the rookie mind so the canary exercises the stall it
    vouches for, never whatever the router prefers (the 0019 wart). Route honored via
    executable() (0020's law: authorize is truth for routing, keys are truth for
    execution) with the honest refund when this floor holds no key. Becky's tokens
    chain to the pinned root, so every floor's stable earns its canary thought — not
    just the join floor. Silently skipped when no provider key or litellm is around
    (canary then rests on verified syncs alone)."""
    try:
        import litellm  # noqa: F401
    except Exception:
        return None
    if not (os.environ.get("ANTHROPIC_API_KEY") or os.environ.get("OPENAI_API_KEY")
            or os.environ.get("OPENROUTER_API_KEY")):
        return None
    try:
        token = _BECKY.issue_token(ADA_DID, SCOPE, [{"action": "retrieve", "space": "self"}],
                                   budget={"tokens": 50000})
        est = 40
        grant = call(port, "POST", "/model/authorize",
                     {"token": token, "class": klass, "est_tokens": est, "model": mid})
        model = executable(port, grant["model"])
        if model is None:                 # honest refund: authorized, but no key to execute
            call(port, "POST", "/model/meter",
                 {"subject": grant["subject"], "est_tokens": est, "tokens": 0, "usd": 0,
                  "model": grant["model"], "class": klass})
            FLIGHT.refuse(ADA_DID, klass, "no-local-key")
            return None
        import litellm
        t0 = time.perf_counter()
        resp = litellm.completion(model=model,
                                  messages=[{"role": "user", "content": "ping"}],
                                  max_tokens=1)
        ms = int((time.perf_counter() - t0) * 1000)
        tokens = resp.usage.total_tokens
        try:
            usd = litellm.completion_cost(completion_response=resp)
        except Exception:
            usd = 0.0
        call(port, "POST", "/model/meter",
             {"subject": grant["subject"], "est_tokens": est, "tokens": tokens,
              "usd": round(usd, 6), "model": grant["model"], "class": klass})
        FLIGHT.note(caller=ADA_DID, klass=klass, model=grant["model"],
                    tokens=tokens, usd=usd, ms=ms)
        return {"model": grant["model"], "tokens": tokens}
    except Exception:
        FLIGHT.refuse(ADA_DID, klass, "stumbled")
        return None


# ---------------------------------------------------------------- the canon firmware (0045 sp1)
